const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const westernPacific = ee.Geometry.Rectangle([130, -5, 160, 20]);
  const startYear1 = '1998-01-01';
  const endYear1 = '1998-12-31';
  const startYear2 = '2009-01-01';
  const endYear2 = '2009-12-31';

  // 2. Data Acquisition & Check
  const trmmCollection = ee.ImageCollection('TRMM/3B42').select('precipitation');

  const collection1998 = trmmCollection.filterDate(startYear1, endYear1).filterBounds(westernPacific);
  const collection2009 = trmmCollection.filterDate(startYear2, endYear2).filterBounds(westernPacific);

  const size1998 = collection1998.size().getInfo();
  const size2009 = collection2009.size().getInfo();

  console.log(`Image count for 1998: ${size1998}`);
  console.log(`Image count for 2009: ${size2009}`);

  if (size1998 === 0 || size2009 === 0) {
    console.log("Evidence: No images found for one or both years in the specified region.");
    console.log("C1");
    return;
  }

  // 3. Processing & Calculation
  const mean1998 = collection1998.mean();
  const mean2009 = collection2009.mean();

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1998 = mean1998.reduceRegion({
    reducer: reducer,
    geometry: westernPacific,
    scale: 25000, // Native resolution is ~27km (0.25 deg), so this is a safe scale.
    maxPixels: 1e9
  }).getInfo();

  const stats2009 = mean2009.reduceRegion({
    reducer: reducer,
    geometry: westernPacific,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const count1998 = stats1998['precipitation_count'];
  const count2009 = stats2009['precipitation_count'];

  if (!count1998 || count1998 === 0 || !count2009 || count2009 === 0) {
    console.log(`Pixel count 1998: ${count1998}`);
    console.log(`Pixel count 2009: ${count2009}`);
    console.log("Evidence: No valid pixels found after processing.");
    console.log("C2");
    return;
  }

  const meanRainfall1998 = stats1998['precipitation_mean'];
  const meanRainfall2009 = stats2009['precipitation_mean'];

  // 4. Validation & Final Answer
  if (meanRainfall1998 === null || meanRainfall2009 === null) {
      console.log(`1998 Mean Rainfall: ${meanRainfall1998}`);
      console.log(`2009 Mean Rainfall: ${meanRainfall2009}`);
      console.log("Evidence: Calculation resulted in a null value.");
      console.log("C3");
      return;
  }

  console.log(`1998 Avg Rainfall (mm/hr): ${meanRainfall1998.toFixed(4)}, Pixels: ${count1998}`);
  console.log(`2009 Avg Rainfall (mm/hr): ${meanRainfall2009.toFixed(4)}, Pixels: ${count2009}`);

  if (meanRainfall2009 > meanRainfall1998) {
    console.log("Evidence: The average rainfall rate in 2009 was higher than in 1998.");
    console.log("A");
  } else {
    console.log("Evidence: The average rainfall rate in 2009 was not higher than in 1998.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject, null);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
